INSERT INTO `comentarios` (`id`, `comentario`, `usuario`) VALUES
(1, 'Se acerca la Copa America', 'Profetamundial'),
(2, '¡Ya se puede pronosticar la Copa America!', 'seblash'),
(3, 'Finalizado el plazo para hacer modificaciones en el pronostico de la Copa America Argentina 2011.', 'seblash'),
(4, 'handry y marcelo primeros lideres de la Copa America con 5 puntos cada uno.', 'ProfetaMundial'),
(5, 'HAY QUE SER PROFETA PARA PONER UN 0-0 A BRASIL-VENEZUELA!!!', 'santiago'),
(6, '<span style="color:orange;">¡IMPORTANTE! </span>Error de visualizacion en el partido Uruguay-Mexico. Los resultados de los participantes ya se muestran de forma correcta. Disculpen las molestias', 'ProfetaMundial'),
(7, 'Lider de la primera fase, menudo profeta jejeje', 'Marcelo'),
(8, 'Nadie puso a Peru en Cuartos, y ya esta en semifinales...', 'seblash'),
(9, 'Ni el mejor profeta podia ver que Venezuela iba a jugar una semifinal...', 'seblash'),
(10, 'Ahora todo depende de Uruguay y de los goleadores. Si el Kun es goleador en solitario, el ganador sera Pablo. Si Uruguay sale campeon (y lo anterior no pasa) la ganadora sera Handry.', 'seblash'),
(11, 'Marcelo necesita que Suarez meta 3 goles o cualquier otro jugador sume 4. Aunque Uruguay quedase tercero, no le alcanzaria para ganar.', 'seblash'),
(12, '<span style="color:orange;">¡¡FELICIDADES HANDRY!!</span> Ganadora del pronostico Copa America Argentina 2011', 'ProfetaMundial'),
(13, '¡Proximamente disponible la Eurocopa 2012 y pronostico para los Juegos Olimpicos London 2012!', 'ProfetaMundial'),
(14, '<span style="color:orange;font-weight:bold; background-color:black; padding:2px;">¡Nuevo!</span> ¡Ya esta disponible el pronostico para los Oscar 2012!', 'ProfetaMundial'),
(15, 'A las 23:59 CET se cierra el plazo de participacion o modificacion del pronostico Oscar 2012.', 'seblash'),
(16, 'Hay que tener cara dura para darle premios a la dama de hierro...Aunque no sé de qué me sorprendo.', 'felipescu'),
(17, 'cara dura hay que tener tambien para dar el premio al mejor actor a uno que no habla en toda la pelicula', 'santiago'),
(18, 'quien gano', 'Marcelo'),
(19, 'quien va a ganar papa|||', 'santiago'),
(20, 'no veo ninguna felicitacion al ganador, eh que pasa', 'santiago'),
(21, 'Donde está el administrador de la página que no puso aún los resultados?', 'santiago'),
(22, 'Aunque falta el recuento oficial, parece que el vencedor es claro con gran diferencia.<br /><span style="color:orange"> ¡Felicidades santiago!</span>', 'ProfetaMundial'),
(23, 'Felicidades Santiago !!!!!!!!!!\r\n\r\n', 'PABLO'),
(24, 'And the winner, in best oscar''s forecast is:......\r\nSANTIAGO, for "Super orto", Congratulations!', 'felipescu'),
(25, '<span style="background-color:red;color:white; padding:3px;"><b> ¡Nuevo!</b> </span> ¡Ya esta disponible el pronostico para la Eurocopa 2012!', 'ProfetaMundial'),
(26, '<span style="color:orange">!IMPORTANTE¡ </span> Debido a problemas en la organizacion de la Euro 2012, algunos pronosticos fueron alterados. Se envio un email a los afectados por este problema. ', 'ProfetaMundial'),
(27, 'El  futbolista de la selección de Croacia cree que al combinado español le pasará factura el cansancio que acumulan sus jugadores, sobre todo los del Real Madrid y del Barcelona, y no la considera como la favorita ', 'santiago'),
(28, 'Klose:El atacante alemán, concentrado ya con su selección, arrastra desde hace semanas molestias musculares, por lo que estos días pasará varias revisiones para valorar su alcance.', 'santiago'),
(29, 'Carles Puyol, Bacary Sagna y Chris Smalling son las últimas bajas confirmadas por lesión para la Eurocopa. Jugadores como Scott Parker, Rio Ferdinand o Johan Elmander atraviesan  problemas físicos', 'santiago'),
(30, 'Bale, Dzeko, Hamsik, Hazard... Todos ellos futbolistas situados entre los mejores del mundo pero que no optarán a la disputa del torneo que centrará todos los focos de atención en el mes de junio.', 'santiago'),
(31, '¿Entre los mejores del mundo? Un poquito exagerado, ¿no?', 'seblash'),
(32, 'fernando, ¡guarda, que no elegiste al campeon!', 'seblash'),
(33, ' <span style="color:orange;">¡IMPORTANTE!</span> Cambios en las reglas, en lo referente a empate a puntos entre dos o mas equipos del mismo grupo.', 'ProfetaMundial'),
(34, 'Finalizado el plazo para participar en la Euro 2012. ¡Mucha suerte a todos los pronosticadores!', 'ProfetaMundial'),
(35, 'curioso que de los 24 partidos de fase de grupos,solo estamos de acuerdo los 11 que participamos en 4:españa gana a irlanda y croacia,alemania gana a dinamarca e inglaterra a ucrania', 'santiago'),
(36, 'Pena que no me salio el resultado de Polonia jejjejej en fin ', 'josito'),
(37, 'Ya líder jejejeje', 'Marcelo'),
(38, 'poco te duro lo de lider, aqui esta el tipster\r\n', 'santiago'),
(39, 'santi putoo cuanto le pagaste a los putos rusos, para ganar el resultado,ijijijij ', 'josito'),
(40, 'Primer gran sorpresa general. 0 puntos para todos y un favorito complicado...', 'seblash'),
(41, 'putos holandeses ni un gol.', 'josito'),
(42, 'joder aun sigo con mi casillero a 0, siempre ahi ahi pero no hay manera,ijijijij', 'josito'),
(43, 'Josito como quedes con 0 puntos te doy un premio jajajaja', 'santiago'),
(44, 'ya ves puto siempre muy cerca pero nada, es lo que hay ijijijijij', 'josito'),
(45, 'putooo ya no estas solo de lider ehhh, ya estas a fallar un poco ijijijij', 'josito'),
(46, 'Felicidades josito! Ya tenes tu primer puntito!', 'seblash'),
(47, 'gracias sebas sin tiempo no era, siempre ahi casi casi pero no daba frutos mis pronosticos ijijij, y al puto de santy decirte que ya tengo mi primer puntito y que SANTYY putoooo siento que ya dejaras de ser lider, que poco te duro ijijijijijij\r\n', 'josito'),
(48, 'Y chicos hacerme ya huecco ahi arriba que ahora ya cogi carrerrilla ijijijijijij FIESTAAAAAAAAAAAAA. Enhorabuena para el que esta de lider por el momento , hasta que llegue yo ijijijij.', 'josito'),
(49, 'No pasa nada mañana recupero mi sitio\r\nAdrián culo rotooooo!!', 'santiago'),
(50, 'Vos si que tenes el culo rotoo, ala ajo y agua puto ya no creo que recuperes mas el lider ijijijijij, se siente.', 'josito'),
(51, 'que ortooooo tenesss putoooo santyyy', 'josito'),
(52, 'que bien se se va uno a cama siendo lider!!', 'santiago'),
(53, 'Pero vamos a ver, aun sigues estando de lider cacho putoo tu sii que tener un ortoooooooooooooooooooo.', 'josito'),
(54, 'por fin acierto un putoo resultado ijijijijijijijij', 'josito'),
(55, 'Hoy fue el dia de Pablo...', 'seblash'),
(56, 'El Glasgow Rangers dejó de existir\r\nEl club más ganador de la historia del fútbol escocés se declaró en bancarrota por una deuda de 26 millones de euros al fisco local, y debió ser refundado como "The Rangers Football Club". Jugará en tercera división', 'santiago'),
(57, '5 puntos para 7! En esto si que estabamos de acuerdo.. ', 'seblash'),
(58, 'Chau Dzagoev...', 'seblash'),
(59, 'Chau Van Persie, Chau Holanda...', 'seblash'),
(60, 'me cago en todo, putos portugeses, casi hago pleno hoy ijijij ', 'josito'),
(61, 'Ya estan sumados los extras por coincidencias en los Cuartos de Final', 'ProfetaMundial'),
(62, 'marcelo no quiero ser yeta, pero esta vez si que esta dificil que se te escape... ', 'seblash'),
(63, 'ehh sebas te olvidas de mi igual le gano yo ijijijijijij', 'josito'),
(64, 'Se acerca fernando, que tiene una semifinal Alemania-Italia', 'seblash'),
(65, 'Chau Alemania, chau Mario Gomez, Muller y Schurle', 'seblash'),
(66, '<span style="color:orange;font-weight:bold;">¡¡¡FELICIDADES MARCELO!!!</span>\r\n¡Campeon Eurocopa Polonia-Ucrania 2012!', 'ProfetaMundial'),
(67, 'Felicidades marcelo, aunque sufriste por si metía torres otro gol eheheheh', 'santiago'),
(68, 'Marcelo, casi te cagan con el cuarto si lo metia Torres, jajaja. \r\nFelicidades!', 'seblash'),
(69, 'Torres pichichi , tongo .', 'PABLO'),
(70, '<i>El usuario que inscriba como goleador el apellido del jugador, o UNO DE LOS JUGADORES que se adjudique mas goles en la Euro 2012 Polonia-Ucrania</i>\r\n\r\nTorres, Dzagoeb y Gomez fueron puntuados ', 'seblash'),
(71, '<span style="background-color:red;color:white; padding:3px;"><b> ¡Nuevo!</b> </span> ¡Ya esta disponible el pronostico para el futbol masculino en los Juegos Olimpicos Londres 2012!', 'ProfetaMundial'),
(72, 'El plazo para participar en el pronostico para el futbol masculino en los Juegos Olimpicos Londres 2012 ha finalizado.', 'ProfetaMundial'),
(73, 'Poquitos aciertos el primer dia...', 'seblash'),
(74, '...', 'seblash'),
(75, 'Solo handry tiene posibilidad de puntuar con los partidos de hoy.', 'seblash'),
(76, 'santiago acaricia el titulo...', 'seblash'),
(78, 'santiago, ahora si , acaricia el titulo...', 'seblash'),
(79, '<span style="color:orange;font-weight:bold;">¡¡¡FELICIDADES SANTIAGO!!!</span><br />Oro en Futbol Masculino en las Olimpiadas Londres 2012', 'ProfetaMundial'),
(80, '<span style="background-color:red;color:white; padding:3px;"><b> ¡Nuevo!</b> </span>\r\n ¡Ya esta disponible el pronostico para los Premios Oscar 2013!', 'ProfetaMundial'),
(81, '¡Ultimo dia para pronosticar!', 'seblash'),
(82, 'Finalizado el plazo para participar en el pronostico Oscar 2013. Suerte a los participantes.', 'ProfetaMundial'),
(83, 'quien esta puntuando?\r\n', 'santiago'),
(84, '¡Felicidades santiago!¡Ganador Oscar 2013!', 'ProfetaMundial'),
(85, 'Disponible el pronostico para la Copa Confederaciones Brasil 2013', 'ProfetaMundial'),
(86, 'Plazo finalizado para participar en el pronostico de la Copa Confederaciones Brasil 2013', 'ProfetaMundial'),
(87, 'Apasionante empate a puntos antes de la final!\r\nAdemas uno tiene a España y el otro a Brasil.\r\nHandry tiene a Torres de goleador.', 'seblash'),
(88, '<span style="color:orange;font-weight:bold;">¡¡¡FELICIDADES MARCELO!!!</span>\r\n¡Campeon Copa Confederaciones Brasil 2013!', 'ProfetaMundial'),
(89, 'Felicidades campeón', 'santiago'),
(90, 'Gracias,fue un disputa,hasta el último partido', 'Marcelo'),
(91, 'Proximamente disponible el pronostico para la Copa del mundo de la FIFA Brasil 2014', 'ProfetaMundial'),
(92, '¡Felicidades Santiago! Ganador Pronostico Oscar 2014.', 'ProfetaMundial'),
(93, 'Tercer titulo consecutivo con ¡19 aciertos!... Impresionante', 'seblash'),
(94, 'No sabía que los de lanús entendían de fútbol', 'santiago'),
(95, 'Las gallinas seocultan detras de otronombre JA JA\r\n', 'Dale Lanus'),
(96, 'Después del mundial veremos quien saca mas puntos\r\nLos de RiBer entran en la sudamericana para quelos elimine Lanus', 'Dale Lanus'),
(97, 'Lista mejores jugadores sudamericanos del siglo XX de la IFFHS argentinos:\r\nMaradona (2)\r\nDi Stefano (3)\r\nMoreno (5)\r\nPedernera (12)\r\nSívori (16)\r\nKempes (23)\r\nLabruna (26)\r\n6 son de RIVER y de lanus?', 'santiago'),
(98, 'Maradona (2)\r\nDi Stefano (3)\r\nMoreno (5)\r\nPedernera (12)\r\nSívori (16)\r\nKempes (23)\r\nLabruna (26)\r\nPassarella (35)\r\nOrsi (43)', 'santiago'),
(99, '<i>Recordamos a los participantes:</i><br />\r\nEl plazo para participar y modificar el pronostico para el Mundial 2014 finaliza el <b>Martes 10 de Junio de 2014 a las 23:00 horas (GMT)</b>', 'ProfetaMundial'),
(100, 'Pronostico Mundial 2014, plazo finalizado. ¡Buena suerte a los participantes!', 'ProfetaMundial');

