--
-- Table structure for table `partidos_conf`
--

DROP TABLE IF EXISTS `partidos_conf`;
CREATE TABLE IF NOT EXISTS `partidos_conf` (
  `CodUsu` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT NULL,
  `CodPar` int(99) DEFAULT NULL,
  `local` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT NULL,
  `visitante` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT NULL,
  `glocal` int(20) DEFAULT '0',
  `gvisitante` int(20) DEFAULT '0',
  `resultado` int(20) DEFAULT '0',
  `fecha` date NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

